// Which path-scoped skills become available in each session, from the files that session touched.
import { readFileSync, readdirSync } from "node:fs";
import { matchesGlob } from "node:path";

const skills = readdirSync("skills").map((name) => {
  const head = readFileSync(`skills/${name}/SKILL.md`, "utf8").split("---")[1];
  const paths = JSON.parse(head.match(/^paths:\s*(.*)$/m)?.[1] ?? "[]");
  return { name, paths };
});

for (const s of JSON.parse(readFileSync("sessions.json", "utf8"))) {
  const on = skills.filter((k) => s.touched.some((f) => k.paths.some((p) => matchesGlob(f, p)))).map((k) => k.name);
  console.log(`${s.task.padEnd(36)} → ${on.join(", ") || "(no codebase skill)"}`);
}
EOF
